-- SwayNC
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.layer_rule({ match = { namespace = "swaync-control-center" }, blur = true, ignore_alpha = 0.5 })
hl.layer_rule({ match = { namespace = "swaync-notification-window" }, blur = true, ignore_alpha = 0.5 })

-- Pavucontrol
hl.window_rule({
    name = "pavucontrol",
    match = {
        class = "(.*org.pulseaudio.pavucontrol.*)",
    },
    float = true,
    center = true,
    pin = true,
    size = "700 600",
})

-- Waypaper
hl.window_rule({
    name = "waypaper",
    match = {
        class = "(.*waypaper.*)",
    },
    float = true,
    center = true,
    pin = true,
    size = "900 700",
})

